sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiValues = {
        'data': []
    };

    try {
        // Aggregate publisher counts
        var gr = new GlideRecord('core_company');

        gr.query();

        // Check if no records were returned
        if (!gr.hasNext()) {
            gs.info("No records found in cmdb_sam_sw_discovery_model.");
        }

        // Loop through the records
        while (gr.next()) {
            var publisherID = gr.getDisplayValue('name'); // Get publisher sys_id

            // Log publisher ID and count for debugging
            // gs.info("Publisher ID: " + publisherID + " | Publisher Count: " + publisherCount);

            kpiValues.data.push({"itemId":"checkbox_0","checked":false,"required":true,"order":0,"label": publisherID , "hasLink":true,"link":{"url":"javascript:void(0)","text":"sample link 0"}}

			);
        }

        // If no data was found for publishers, log the result

        gs.info("Transformed KPI Data: " + JSON.stringify(kpiValues));

    } catch (e) {
        // Error handling and logging the error to the ServiceNow logs
        gs.error("Error in transform script: " + e.toString());
        return {
            'error': e.toString() // Return error details for debugging
        };
    }



	var data = [{"itemId":"checkbox_0","checked":false,"required":true,"order":0,"label":"this is test1 0","hasLink":true,"link":{"url":"javascript:void(0)","text":"sample link 0"}},{"itemId":"checkbox_1","checked":false,"order":1,"label":"this is item 1","hasLink":true,"link":{"url":"javascript:void(0)","text":"sample link 1"}},{"itemId":"checkbox_2","checked":false,"order":2,"label":"this is item 2","hasLink":true,"link":{"url":"javascript:void(0)","text":"sample link 2"}},{"itemId":"checkbox_3","checked":false,"order":3,"label":"this is item 3","hasLink":true,"link":{"url":"javascript:void(0)","text":"sample link 3"}}]
    // Return the transformed data
    // return {data : data};
    return kpiValues;
}
